input.command:
t() { local s="$1"; local n=$(printf '%s' "$s" | wc -c); printf 'bytes=%-6s : ' "$n"; /workspace/dataset/test4_executable "$s" | tr '\n' ' '; echo; }
big() { head -c $1 /dev/zero | tr '\0' 'a'; }
echo "== integer wraparound probes (uint8/int16/uint16 aliasing) =="
for n in 256 257 511 512 1000 32767 32768 32769 33023 65279 65535 65536 65537 65791 65792 66000 131071 131072; do
  s=$(big $n); printf 'n=%-7s ' $n; t "$s"
done

rep() { local n=$1 c=$2 s=""; for ((i=0;i<n;i++)); do s+="$c"; done; printf '%s' "$s"; }
t() { local s="$1"; local n=$(printf '%s' "$s" | wc -c); printf 'bytes=%-4s : ' "$n"; /workspace/dataset/test4_executable "$s" | tr '\n' ' '; echo; }
echo "== label boundary, ASCII =="; for n in 62 63 64; do printf 'a*%-3s ' $n; t "$(rep $n a)"; done
echo "== label boundary, 3-byte CJK (21cp=63B) =="; for n in 20 21 22; do printf 'ex*%-3s cp=%-3s ' $n $n; t "$(rep $n '例')"; done
echo "== label straddle: N ascii + one 例 =="; for N in 60 61 62; do printf 'a*%-3s+ex ' $N; t "$(rep $N a)例"; done
echo "== summary check: line1 == (1<=len<=255) for all above? =="
